"statusLine": {
  "type": "command",
  "command": "input=$(cat); current_dir=$(echo \"$input\" | jq -r '.workspace.current_dir'); model_name=$(echo \"$input\" | jq -r '.model.display_name'); output_style=$(echo \"$input\" | jq -r '.output_style.name'); context_remaining=$(echo \"$input\" | jq -r '.context_window.remaining_percentage // empty'); if git -C \"$current_dir\" rev-parse --git-dir > /dev/null 2>&1; then git_branch=$(git -C \"$current_dir\" --no-optional-locks symbolic-ref --short HEAD 2>/dev/null || echo \"detached\"); git_info=\" [$git_branch]\"; else git_info=\"\"; fi; if [ -n \"$context_remaining\" ]; then context_info=\" | Context: ${context_remaining}% remaining\"; else context_info=\"\"; fi; printf \"%s%s | %s | %s%s\" \"$current_dir\" \"$git_info\" \"$model_name\" \"$output_style\" \"$context_info\""
}

